50	/// Each scalar is `Option`: `None` means "no config opinion, use
51	/// the built-in default". Profiles are a flat name->spec map.
52	#[derive(Debug, Default, PartialEq)]
53	pub struct Config {
54	    /// Default `--duration` seconds, if configured.
55	    pub duration: Option<f64>,
56	    /// Default `--band-labels` style, if configured.
57	    pub band_labels: Option<BandLabels>,
58	    /// Default `--decimals` count, if configured.
59	    pub decimals: Option<u8>,
